import React, { useState } from 'react';
import { Box, Typography, Button, TextField, InputAdornment, IconButton, Paper } from '@mui/material';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';

export default function App() {
  const [showPassword, setShowPassword] = useState(false);
  const [form, setForm] = useState({ email: '', password: '', brand: '' });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleClickShowPassword = () => setShowPassword((show) => !show);

  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        bgcolor: '#232323',
      }}
    >
      <Paper
        elevation={6}
        sx={{
          display: 'flex',
          width: { xs: '95vw', md: 900 },
          minHeight: 500,
          borderRadius: 4,
          overflow: 'hidden',
          bgcolor: '#232323',
        }}
      >
        {/* Left Side */}
        <Box
          sx={{
            flex: 1,
            bgcolor: 'linear-gradient(135deg, #00ff88 0%, #232323 100%)',
            color: '#fff',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            p: 4,
          }}
        >
          <Typography variant="h4" fontWeight={700} mb={2} align="center" sx={{ color: '#00ff88' }}>
            Welcome Back!
          </Typography>
          <Typography variant="body1" mb={3} align="center" sx={{ color: '#bfffd0' }}>
            Already using Hub Box? Click below to access your dashboard and manage your content easily.
          </Typography>
          <Button variant="outlined" sx={{ color: '#00ff88', borderColor: '#00ff88', fontWeight: 600, borderRadius: 2, px: 4, '&:hover': { bgcolor: '#00ff8822', borderColor: '#00ff88' } }}>
            Go to Login
          </Button>
        </Box>
        {/* Right Side */}
        <Box
          sx={{
            flex: 1.2,
            bgcolor: '#232323',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            p: 4,
          }}
        >
          <Typography variant="h6" color="#00e676" fontWeight={700} mb={1} align="center">
            Join the Hub Box Community
          </Typography>
          <Typography variant="h3" fontWeight={900} mb={2} align="center" sx={{ color: '#00ff88', letterSpacing: 1 }}>
            Create Your Account
          </Typography>
          <TextField
            label="Email Address"
            name="email"
            value={form.email}
            onChange={handleChange}
            fullWidth
            sx={{ mb: 2, input: { color: '#00ff88', background: '#232323' }, label: { color: '#00e676' }, '& .MuiOutlinedInput-root': { background: '#232323', color: '#00ff88', '& fieldset': { borderColor: '#00e676' }, '&:hover fieldset': { borderColor: '#00ff88' }, '&.Mui-focused fieldset': { borderColor: '#00ff88' } } }}
            InputLabelProps={{ style: { color: '#00e676' } }}
          />
          <TextField
            label="Create Password"
            name="password"
            type={showPassword ? 'text' : 'password'}
            value={form.password}
            onChange={handleChange}
            fullWidth
            sx={{ mb: 2, input: { color: '#00ff88', background: '#232323' }, label: { color: '#00e676' }, '& .MuiOutlinedInput-root': { background: '#232323', color: '#00ff88', '& fieldset': { borderColor: '#00e676' }, '&:hover fieldset': { borderColor: '#00ff88' }, '&.Mui-focused fieldset': { borderColor: '#00ff88' } } }}
            InputLabelProps={{ style: { color: '#00e676' } }}
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <IconButton onClick={handleClickShowPassword} edge="end" sx={{ color: '#00ff88' }}>
                    {showPassword ? <VisibilityOff /> : <Visibility />}
                  </IconButton>
                </InputAdornment>
              ),
            }}
          />
          <TextField
            label="Brand/Channel Name (Optional)"
            name="brand"
            value={form.brand}
            onChange={handleChange}
            fullWidth
            sx={{ mb: 2, input: { color: '#00ff88', background: '#232323' }, label: { color: '#00e676' }, '& .MuiOutlinedInput-root': { background: '#232323', color: '#00ff88', '& fieldset': { borderColor: '#00e676' }, '&:hover fieldset': { borderColor: '#00ff88' }, '&.Mui-focused fieldset': { borderColor: '#00ff88' } } }}
            InputLabelProps={{ style: { color: '#00e676' } }}
          />
          <Button
            variant="contained"
            fullWidth
            sx={{
              mt: 1,
              bgcolor: '#00e676',
              color: '#232323',
              fontWeight: 700,
              borderRadius: 2,
              py: 1.2,
              fontSize: 18,
              boxShadow: '0 2px 12px #00e67644',
              '&:hover': { bgcolor: '#00ff88', color: '#232323' },
            }}
          >
            Sign Up Free
          </Button>
          <Typography variant="body2" color="#00ff88" align="center" mt={2}>
            By signing up, you agree to our <span style={{ color: '#00e676', fontWeight: 600 }}>Terms</span> and <span style={{ color: '#00e676', fontWeight: 600 }}>Privacy Policy</span>.
          </Typography>
        </Box>
      </Paper>
    </Box>
  );
}
